-- 388: Original BrillaPrep NSMQ subj_nsmq_math problem_of_day beta questions (batch 001).
-- Curriculum-aligned practice content; not official NSMQ (Primetime) material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_388_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_388_guard;
INSERT INTO _migration_388_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_pod_b001_001' AND NOT (q.topic_id IS 'topic_algebra' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Solve for x: 2(x − 3) + 4 = 3x − 7' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS 'x = 5' AND q.explanation IS 'Expand the brackets: 2x − 6 + 4 = 3x − 7, so 2x − 2 = 3x − 7. Subtract 2x from both sides: −2 = x − 7. Add 7 to both sides: x = 5. Check: 2(5 − 3) + 4 = 4 + 4 = 8 and 3(5) − 7 = 15 − 7 = 8, so the solution x = 5 is consistent.' AND q.difficulty IS 'medium' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_pod_b001_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_388_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_pod_b001_002' AND NOT (q.topic_id IS 'topic_quadratic' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Find the sum of the squares of the roots of x² − 7x + 12 = 0' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS '25' AND q.explanation IS 'Factorise: (x − 3)(x − 4) = 0, so the roots are x = 3 and x = 4. Their squares are 9 and 16, giving a sum of 25. Cross-check with root relations: sum of roots = 7 and product = 12, so sum of squares = 7² − 2(12) = 49 − 24 = 25.' AND q.difficulty IS 'medium' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_pod_b001_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_388_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_pod_b001_003' AND NOT (q.topic_id IS 'topic_geometry' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A cylinder has radius 7 cm and height 10 cm. Using π = 22/7, calculate its volume.' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS '1540 cm³' AND q.explanation IS 'Volume of a cylinder V = πr²h. Substitute r = 7 cm and h = 10 cm: V = (22/7) × 7² × 10 = (22/7) × 49 × 10 = 22 × 7 × 10 = 1540 cm³. The 7 in the denominator cancels with the 49 from r², which is why 22/7 is a convenient approximation here.' AND q.difficulty IS 'medium' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_pod_b001_003' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_388_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_pod_b001_004' AND NOT (q.topic_id IS 'topic_statistics' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A bag contains 3 red and 2 blue balls. Two balls are drawn at random without replacement. What is the probability that both are red?' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS '3/10' AND q.explanation IS 'P(first red) = 3/5. After removing one red ball, 2 red remain out of 4 balls, so P(second red | first red) = 2/4 = 1/2. Multiply because the draws are dependent: P(both red) = 3/5 × 1/2 = 3/10 = 0.3.' AND q.difficulty IS 'hard' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_pod_b001_004' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_math_pod_b001_001', 'topic_algebra', 'subj_nsmq_math', 'exam_nsmq', NULL, NULL, 'Solve for x: 2(x − 3) + 4 = 3x − 7', 'problem', 'problem_of_day', NULL, 'x = 5', 'Expand the brackets: 2x − 6 + 4 = 3x − 7, so 2x − 2 = 3x − 7. Subtract 2x from both sides: −2 = x − 7. Add 7 to both sides: x = 5. Check: 2(5 − 3) + 4 = 4 + 4 = 8 and 3(5) − 7 = 15 − 7 = 8, so the solution x = 5 is consistent.', 'medium', '5', '1', '120', NULL, NULL, '1', NULL, NULL, 'Solve', 'AO2', NULL, NULL, NULL);
