INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_math_pod_b001_003', 'topic_geometry', 'subj_nsmq_math', 'exam_nsmq', NULL, NULL, 'A cylinder has radius 7 cm and height 10 cm. Using π = 22/7, calculate its volume.', 'problem', 'problem_of_day', NULL, '1540 cm³', 'Volume of a cylinder V = πr²h. Substitute r = 7 cm and h = 10 cm: V = (22/7) × 7² × 10 = (22/7) × 49 × 10 = 22 × 7 × 10 = 1540 cm³. The 7 in the denominator cancels with the 49 from r², which is why 22/7 is a convenient approximation here.', 'medium', '5', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_math_pod_b001_004', 'topic_statistics', 'subj_nsmq_math', 'exam_nsmq', NULL, NULL, 'A bag contains 3 red and 2 blue balls. Two balls are drawn at random without replacement. What is the probability that both are red?', 'problem', 'problem_of_day', NULL, '3/10', 'P(first red) = 3/5. After removing one red ball, 2 red remain out of 4 balls, so P(second red | first red) = 2/4 = 1/2. Multiply because the draws are dependent: P(both red) = 3/5 × 1/2 = 3/10 = 0.3.', 'hard', '5', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, NULL);
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'nsmq-expansion-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM questions WHERE id IN ('q_nsmq_math_pod_b001_001', 'q_nsmq_math_pod_b001_002', 'q_nsmq_math_pod_b001_003', 'q_nsmq_math_pod_b001_004');
DELETE FROM _migration_388_guard;
INSERT INTO _migration_388_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions WHERE id IN ('q_nsmq_math_pod_b001_001', 'q_nsmq_math_pod_b001_002', 'q_nsmq_math_pod_b001_003', 'q_nsmq_math_pod_b001_004')) = 4 AND (SELECT COUNT(*) FROM question_content_releases r WHERE r.question_id IN ('q_nsmq_math_pod_b001_001', 'q_nsmq_math_pod_b001_002', 'q_nsmq_math_pod_b001_003', 'q_nsmq_math_pod_b001_004') AND r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 4 THEN 1 ELSE 0 END;
DROP TABLE _migration_388_guard;
